function secondLargestBySorting(nums) {
  const sorted = [...nums].sort((a, b) => b - a);
  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i] !== sorted[0]) return sorted[i];
  }
  return -1;
}

function secondLargest(nums) {
  let largest = -Infinity;
  let second = -Infinity;
  for (const x of nums) {
    if (x > largest) {
      second = largest;   // the old champion becomes the runner-up
      largest = x;
    } else if (x < largest && x > second) {
      second = x;
    }
  }
  return second === -Infinity ? -1 : second;
}

def second_largest(nums):
    largest = second = float("-inf")
    for x in nums:
        if x > largest:
            second, largest = largest, x   # the old champion becomes the runner-up
        elif largest > x > second:
            second = x
    return -1 if second == float("-inf") else second

class Solution {
    public int secondLargest(int[] nums) {
        long largest = Long.MIN_VALUE, second = Long.MIN_VALUE;
        for (int x : nums) {
            if (x > largest) {
                second = largest;   // the old champion becomes the runner-up
                largest = x;
            } else if (x < largest && x > second) {
                second = x;
            }
        }
        return second == Long.MIN_VALUE ? -1 : (int) second;
    }
}

